def transform(grid):
    counts = {}
    for row in grid:
        for cell in row:
            counts[cell] = counts.get(cell, 0) + 1
    # Sort by frequency descending
    items = sorted(counts.items(), key=lambda x: x[1], reverse=True)
    most_val = items[0][0]
    next_val = items[1][0]
    return [[next_val if cell == most_val else 0 if cell == next_val else cell for cell in row] for row in grid]

